head.b:skin:
/* Epoch 1.0.0 — original design by Gonk Themes. GPL-2.0-or-later. */
:root{color-scheme:dark;--ep-bg:#101216;--ep-card:#191c22;--ep-raised:#222731;--ep-text:#f2f4f8;--ep-muted:#aab3c2;--ep-line:#39414f;--ep-accent:#8fbaff;--ep-violet:#b5cfff;--ep-ink:#101b30;--ep-radius:16px;--ep-max:1240px;--ep-body:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;--ep-mono:ui-monospace,SFMono-Regular,Consolas,monospace}
html[data-epoch-mode=paper]{color-scheme:light;--ep-bg:#f4f6fa;--ep-card:#ffffff;--ep-raised:#e7edf6;--ep-text:#162033;--ep-muted:#506078;--ep-line:#bdc9dc;--ep-accent:#2354a0;--ep-violet:#3b5f96;--ep-ink:#fff}
*,*:before,*:after{box-sizing:border-box}html{scroll-padding-top:100px}body{margin:0;background:var(--ep-bg);color:var(--ep-text);font:16px/1.65 var(--ep-body);-webkit-font-smoothing:antialiased}a{color:inherit;text-underline-offset:4px}img,svg,video{max-width:100%}img{height:auto}button,input,select,textarea{font:inherit}button,a,input,summary{touch-action:manipulation}button{cursor:pointer}button:disabled{cursor:wait}a:focus-visible,button:focus-visible,input:focus-visible,summary:focus-visible,textarea:focus-visible{outline:3px solid var(--ep-violet);outline-offset:5px}::selection{background:var(--ep-accent);color:var(--ep-ink)}.ep-wrap{width:min(var(--ep-max),calc(100% - 64px));margin-inline:auto}.ep-skip{position:fixed;top:-100px;left:16px;z-index:100;background:var(--ep-accent);color:var(--ep-ink);padding:12px 18px}.ep-skip:focus{top:12px}.ep-sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.ep-header{border-bottom:1px solid var(--ep-line);background:var(--ep-bg)}.ep-header-inner{display:flex;align-items:center;gap:28px;min-height:94px}.ep-brand{display:flex;align-items:center;gap:12px;font-size:27px;font-weight:750;letter-spacing:-1.4px;text-decoration:none;white-space:nowrap}.ep-mark{width:38px;height:38px;background:var(--ep-accent);color:var(--ep-ink);display:grid;place-items:center;border-radius:10px;font:800 26px/1 var(--ep-body);letter-spacing:-3px;padding-right:3px;transform:rotate(-6deg)}.ep-brand small{font:11px/1.3 var(--ep-mono);color:var(--ep-muted);display:block;letter-spacing:1.1px;text-transform:uppercase}.ep-nav{display:flex;align-items:center;gap:22px;margin-left:auto}.ep-nav a{font-size:14px;text-decoration:none;min-height:44px;display:inline-flex;align-items:center}.ep-nav a:hover,.ep-text-link:hover{color:var(--ep-accent)}.ep-tools{display:flex;gap:8px;align-items:center}.ep-icon{width:44px;min-height:44px;border:1px solid var(--ep-line);background:transparent;color:var(--ep-text);border-radius:50%;display:grid;place-items:center;text-decoration:none}.ep-icon svg{width:19px;height:19px}.ep-mobile{display:none}.ep-mobile summary{cursor:pointer;list-style:none;padding:10px 14px;min-height:44px;border:1px solid var(--ep-line);border-radius:999px;font-size:14px}.ep-mobile summary::-webkit-details-marker{display:none}.ep-mobile nav{position:absolute;inset:85px 16px auto;padding:20px;z-index:10;background:var(--ep-card);border:1px solid var(--ep-line);border-radius:14px;box-shadow:0 15px 40px #0005}.ep-mobile nav a{display:block;padding:12px;text-decoration:none}.ep-mobile[open] summary{color:var(--ep-accent)}
.ep-eyebrow{font:12px/1.5 var(--ep-mono);letter-spacing:1.5px;text-transform:uppercase;color:var(--ep-muted);display:flex;gap:9px;align-items:center}.ep-dot{width:7px;height:7px;border-radius:50%;background:var(--ep-accent);display:inline-block;flex-shrink:0}.ep-hero{display:grid;grid-template-columns:1.2fr 1fr;gap:52px;align-items:center;padding-block:68px 60px;border-bottom:1px solid var(--ep-line)}.ep-hero h1{font-size:clamp(46px,5.6vw,80px);font-weight:650;line-height:1.035;letter-spacing:-4px;margin:24px 0}.ep-hero h1 span{color:var(--ep-accent)}.ep-lead{font-size:17px;max-width:455px;color:var(--ep-muted);line-height:1.8;margin:0 0 28px}.ep-actions{display:flex;gap:18px;flex-wrap:wrap;align-items:center}.ep-button{min-height:46px;padding:12px 21px;border-radius:999px;background:var(--ep-accent);color:var(--ep-ink);display:inline-flex;align-items:center;justify-content:center;gap:14px;text-decoration:none;font-size:14px;font-weight:650;border:1px solid transparent;transition:transform .18s,background .18s}.ep-button:hover{transform:translateY(-2px)}.ep-button:active{transform:translateY(0)}.ep-button.secondary{background:transparent;color:var(--ep-text);border-color:var(--ep-line)}.ep-text-link{font-size:14px;min-height:44px;display:inline-flex;align-items:center;gap:12px;text-decoration:none}.ep-cover{position:relative;border:1px solid #3e4e65;border-radius:var(--ep-radius);aspect-ratio:1.12;overflow:hidden;background:#171e2a url('data:image/svg+xml;base64,') center/cover}.ep-cover:after{content:"";position:absolute;width:90px;height:90px;border:1px solid #8fbaff65;border-radius:50%;top:26%;left:32%;animation:ep-orbit 18s linear infinite;transform-origin:90px 70px;pointer-events:none}.ep-cover-top{position:absolute;inset:24px 24px auto;display:flex;justify-content:space-between;color:#c2d0e4;font:11px/1.5 var(--ep-mono);letter-spacing:1px}.ep-cover-bottom{position:absolute;inset:auto 24px 22px;color:#e5eefc;font-size:14px;display:flex;justify-content:space-between;align-items:end}.ep-cover-bottom strong{font-size:31px;line-height:1.1;font-weight:500;letter-spacing:-1px}.ep-cover-bottom small{display:block;font:10px/1.5 var(--ep-mono);color:#b0c9ed;letter-spacing:1px;margin-bottom:9px}.ep-caption{font:11px/1.6 var(--ep-mono);color:var(--ep-muted);margin-top:10px}
.ep-topics{display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding-block:22px;border-bottom:1px solid var(--ep-line)}.ep-topics>span{font:11px/1.5 var(--ep-mono);letter-spacing:1px;margin-right:14px;color:var(--ep-muted)}.ep-chip{border:1px solid var(--ep-line);border-radius:999px;padding:9px 15px;text-decoration:none;font-size:13px;min-height:44px;display:inline-flex;align-items:center;gap:7px;transition:background .18s,border-color .18s}.ep-chip:hover{border-color:var(--ep-accent);background:var(--ep-raised)}.ep-content-grid{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:48px;padding-block:46px 64px}.ep-content-grid>*,.ep-card-grid>*{min-width:0}.ep-section-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;margin:0 0 25px}.ep-section-heading h2{font-size:26px;letter-spacing:-.9px;font-weight:600;margin:0}.ep-section-heading p{font:11px var(--ep-mono);color:var(--ep-muted);letter-spacing:1px;margin:0}.ep-card-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:28px 24px}.ep-card{border-bottom:1px solid var(--ep-line);padding-bottom:24px}.ep-card-image{aspect-ratio:16/10;border-radius:12px;display:block;background:var(--ep-raised);overflow:hidden;margin-bottom:18px}.ep-card-image img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .35s}.ep-card-image:hover img{transform:scale(1.035)}.ep-meta{display:flex;align-items:center;gap:10px;font:11px/1.65 var(--ep-mono);color:var(--ep-muted);flex-wrap:wrap}.ep-category{color:var(--ep-accent);text-decoration:none;text-transform:uppercase;letter-spacing:.6px}.ep-card h3{font-size:23px;letter-spacing:-.6px;font-weight:600;line-height:1.3;margin:12px 0 10px}.ep-card h3 a{text-decoration:none}.ep-card h3 a:hover{color:var(--ep-accent)}.ep-card p{font-size:14px;line-height:1.75;color:var(--ep-muted);margin:0 0 17px}.ep-card .ep-byline{font-size:12px;color:var(--ep-muted);display:flex;align-items:center;gap:9px}.ep-avatar{display:inline-grid;place-items:center;background:var(--ep-raised);border:1px solid var(--ep-line);border-radius:50%;width:28px;height:28px;font:10px var(--ep-mono);color:var(--ep-text)}.ep-pagination{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;margin-top:30px}.ep-pagination a{padding:10px 17px;border:1px solid var(--ep-line);border-radius:999px;font-size:14px;text-decoration:none;min-height:44px;display:inline-flex;align-items:center}.ep-pagination a:hover{border-color:var(--ep-accent)}
.ep-rail{border-left:1px solid var(--ep-line);padding-left:28px}.ep-rail h2{font-size:18px;letter-spacing:-.4px;font-weight:600;margin:0 0 18px}.ep-search{display:flex;gap:8px;margin-bottom:34px}.ep-search input{width:100%;min-width:0;border:1px solid var(--ep-line);background:var(--ep-card);color:var(--ep-text);padding:11px;border-radius:8px;font-size:13px;min-height:44px}.ep-search button{border:0;background:var(--ep-accent);color:var(--ep-ink);border-radius:8px;min-width:44px}.ep-note{border:1px solid var(--ep-line);border-top:3px solid var(--ep-violet);border-radius:12px;padding:23px;margin-bottom:30px;background:var(--ep-card)}.ep-note .ep-eyebrow{color:var(--ep-violet);font-size:10px}.ep-note h2{font-size:28px;letter-spacing:-1px;line-height:1.2;margin:15px 0}.ep-note p{font-size:13px;color:var(--ep-muted);line-height:1.85;margin:0 0 12px}.ep-note .ep-text-link{font-size:13px}.ep-list{list-style:none;padding:0;margin:0 0 28px;counter-reset:ep}.ep-list li{border-bottom:1px solid var(--ep-line);padding:16px 0;display:grid;grid-template-columns:25px 1fr;gap:12px;counter-increment:ep}.ep-list li:before{content:counter(ep,decimal-leading-zero);font:12px var(--ep-mono);color:var(--ep-violet);padding-top:4px}.ep-list a{font-size:14px;line-height:1.5;text-decoration:none}.ep-list a:hover{color:var(--ep-accent)}.ep-list small{display:block;color:var(--ep-muted);font:11px var(--ep-mono);margin-top:8px}.ep-rail-links{display:grid;gap:0;margin-bottom:28px}.ep-rail-links a{border-bottom:1px solid var(--ep-line);padding:12px 0;min-height:44px;font-size:13px;text-decoration:none;display:flex;justify-content:space-between;gap:10px}.ep-rail-links a:hover{color:var(--ep-accent)}.ep-rss{border:1px solid var(--ep-line);border-radius:12px;padding:20px;background:var(--ep-raised)}.ep-rss p{font-size:13px;color:var(--ep-muted);margin:10px 0 16px}.ep-rss h2{margin:0;font-size:18px}.ep-rss .ep-button{font-size:12px;width:100%}
.ep-banner{padding:35px 38px;border:1px solid var(--ep-line);background:var(--ep-card);border-radius:16px;display:flex;gap:25px;justify-content:space-between;align-items:center;margin-bottom:64px}.ep-banner h2{font-size:28px;line-height:1.25;letter-spacing:-1px;margin:7px 0 12px;font-weight:600}.ep-banner p{color:var(--ep-muted);font-size:14px;margin:0;max-width:650px}.ep-banner .ep-eyebrow{color:var(--ep-violet)}.ep-footer{border-top:1px solid var(--ep-line);padding-block:38px 28px}.ep-footer-top{display:flex;justify-content:space-between;gap:30px;align-items:start;margin-bottom:30px}.ep-footer p{font-size:13px;color:var(--ep-muted);max-width:330px}.ep-footer-links{display:flex;gap:25px;flex-wrap:wrap;font-size:13px}.ep-footer-links a{min-height:44px;display:inline-flex;align-items:center;text-decoration:none}.ep-footer-bottom{border-top:1px solid var(--ep-line);padding-top:22px;display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;font:11px/1.8 var(--ep-mono);color:var(--ep-muted)}.ep-credit a{color:var(--ep-accent);text-decoration:none}.ep-demo-note{padding:10px 20px;background:var(--ep-raised);color:var(--ep-muted);text-align:center;font:11px/1.6 var(--ep-mono)}
.ep-article{max-width:780px;margin:0 auto;padding:48px 0 64px}.ep-breadcrumb{font:12px var(--ep-mono);color:var(--ep-muted);margin-bottom:24px;display:flex;gap:12px;flex-wrap:wrap}.ep-breadcrumb a{text-decoration:none}.ep-article h1{font-size:clamp(36px,4.7vw,62px);font-weight:600;letter-spacing:-2px;line-height:1.1;margin:18px 0 25px}.ep-article-lead{font-size:21px;line-height:1.65;color:var(--ep-muted)}.ep-article-hero{border-radius:16px;width:100%;margin:28px 0 8px;display:block}.ep-prose{font-size:18px;line-height:1.9;overflow-wrap:anywhere}.ep-prose h2{font-size:30px;font-weight:600;letter-spacing:-1px;line-height:1.3;margin:42px 0 18px}.ep-prose h3{font-size:23px;line-height:1.4;margin-top:28px}.ep-prose p{margin:0 0 23px}.ep-prose a{color:var(--ep-accent)}.ep-prose li{margin-bottom:9px}.ep-prose blockquote{border-left:3px solid var(--ep-violet);margin:30px 0;padding:18px 26px;background:var(--ep-card);font-size:23px;line-height:1.6}.ep-prose pre{padding:22px;border:1px solid var(--ep-line);background:var(--ep-card);overflow:auto;border-radius:12px;font-size:14px}.ep-prose code{font-family:var(--ep-mono);font-size:.85em}.ep-prose table{display:block;max-width:100%;overflow:auto;border-collapse:collapse;font-size:15px}.ep-prose th,.ep-prose td{padding:12px 16px;border:1px solid var(--ep-line);text-align:start}.ep-prose th{background:var(--ep-raised)}.ep-toc{padding:23px;border:1px solid var(--ep-line);border-radius:12px;background:var(--ep-card);margin:25px 0}.ep-toc summary{cursor:pointer;font-size:14px;min-height:30px}.ep-toc a{font-size:14px;color:var(--ep-muted)}.ep-author{border-block:1px solid var(--ep-line);padding:24px 0;margin:35px 0;display:flex;gap:18px}.ep-author p{margin:0;font-size:14px;color:var(--ep-muted)}.ep-share{display:flex;gap:10px;flex-wrap:wrap;margin-block:25px}.ep-share a,.ep-share button{border:1px solid var(--ep-line);background:transparent;color:var(--ep-text);font-size:13px;padding:10px 16px;border-radius:999px;min-height:44px;text-decoration:none}.ep-share a:hover,.ep-share button:hover{border-color:var(--ep-accent)}.ep-archive-head{padding:48px 0 10px}.ep-archive-head h1{font-size:48px;letter-spacing:-2px;line-height:1.15;margin:16px 0}.ep-empty{padding:48px 24px;text-align:center;border:1px solid var(--ep-line);border-radius:16px;grid-column:1/-1}.ep-empty h2{font-size:27px}.ep-empty p{color:var(--ep-muted)}.ep-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:30px 0}.ep-stat{padding:20px;border:1px solid var(--ep-line);border-radius:12px}.ep-stat strong{font-size:27px;display:block}.ep-stat span{font-size:13px;color:var(--ep-muted)}
/* Native Blogger widgets and content. */
.ep-blogger .widget{margin:0}.ep-blogger .post-body{line-height:1.9;overflow-wrap:anywhere}.ep-blogger .post-body img{max-width:100%;height:auto}.ep-blogger .post-body h2{font-size:30px;margin-top:40px}.ep-blogger .post-body iframe{max-width:100%}.ep-blogger .post-body table{display:block;max-width:100%;overflow:auto}.ep-blogger .Label ul,.ep-blogger .PageList ul{padding:0;list-style:none}.ep-blogger .Label li{padding:10px 0;border-bottom:1px solid var(--ep-line);font-size:14px}.ep-blogger .BlogArchive select{background:var(--ep-card);color:var(--ep-text);border:1px solid var(--ep-line);padding:12px;width:100%}.ep-blogger .sidebar .widget{margin-bottom:28px}.ep-blogger .sidebar .widget h2{font-size:18px}.ep-blogger .PageList ul{display:flex;gap:20px;flex-wrap:wrap;font-size:13px}.ep-blogger #comments{margin-top:35px;padding:25px 0;border-top:1px solid var(--ep-line)}.ep-blogger .comment-form iframe{max-width:100%;background:#fff;border-radius:10px}.ep-blogger .comment-body{overflow-wrap:anywhere}.ep-blogger .comment-block{margin-inline-start:45px}.ep-blogger .comment-header,.ep-blogger .comment-footer{font-size:13px;color:var(--ep-muted)}.ep-blogger .feed-links{font-size:12px;color:var(--ep-muted)}.ep-blogger .status-msg-wrap{margin-bottom:25px}.ep-blogger body#layout .ep-hero{display:none}.ep-blogger .Attribution{font-size:11px;color:var(--ep-muted)}
/* WordPress native blocks: use normal editor controls, no page builder dependency. */
.ep-wp .wp-site-blocks{padding:0}.ep-wp .wp-block-template-part{margin:0}.ep-wp .ep-wrap{padding-inline:0}.ep-wp .wp-block-group{box-sizing:border-box}.ep-wp .ep-card-grid.wp-block-post-template{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));list-style:none;margin:0;padding:0;gap:28px 24px}.ep-wp .ep-card-grid>li{padding-bottom:25px;border-bottom:1px solid var(--ep-line);margin:0}.ep-wp .wp-block-post-featured-image{margin:0 0 16px;aspect-ratio:16/10;border-radius:12px;background:var(--ep-raised);overflow:hidden}.ep-wp .wp-block-post-featured-image img{width:100%;height:100%;object-fit:cover}.ep-wp .wp-block-post-title{font-size:23px;line-height:1.3;font-weight:600;letter-spacing:-.6px;margin:12px 0}.ep-wp .wp-block-post-title a{text-decoration:none}.ep-wp .wp-block-post-excerpt{font-size:14px;color:var(--ep-muted);line-height:1.75;margin:0}.ep-wp .wp-block-post-excerpt__excerpt{margin:0 0 16px}.ep-wp .wp-block-post-terms{font:11px var(--ep-mono);text-transform:uppercase;color:var(--ep-accent)}.ep-wp .wp-block-post-terms a{text-decoration:none}.ep-wp .wp-block-post-date,.ep-wp .wp-block-post-author-name{font:12px var(--ep-mono);color:var(--ep-muted)}.ep-wp .ep-article .wp-block-post-title{font-size:clamp(36px,4.7vw,62px);line-height:1.1;margin:20px 0 25px;letter-spacing:-2px}.ep-wp .ep-article .wp-block-post-content{font-size:18px;line-height:1.9}.ep-wp .ep-article .wp-block-post-content h2{font-size:30px;line-height:1.3;margin-top:40px}.ep-wp .wp-block-query-pagination{gap:15px;margin-top:30px;font-size:14px;display:flex;flex-wrap:wrap}.ep-wp .wp-block-query-pagination a{min-height:44px;padding:10px 16px;border:1px solid var(--ep-line);border-radius:999px;text-decoration:none}.ep-wp .wp-block-search{margin:0 0 28px}.ep-wp .wp-block-search__input{min-width:0;border:1px solid var(--ep-line);background:var(--ep-card);color:var(--ep-text);border-radius:8px;padding:10px}.ep-wp .wp-block-search__button{background:var(--ep-accent);color:var(--ep-ink);border:0;border-radius:8px;min-height:44px;padding:10px 14px;font-size:13px}.ep-wp .ep-rail .wp-block-heading{font-size:18px}.ep-wp .ep-footer .wp-block-site-title{font-size:26px;font-weight:700;letter-spacing:-1px;margin:0}.ep-wp .ep-footer .wp-block-site-title a{text-decoration:none}.ep-wp .wp-block-navigation{font-size:14px}.ep-wp .wp-block-navigation-item__content{padding-block:10px}.ep-wp .wp-block-navigation__responsive-container.is-menu-open{padding:28px;background:var(--ep-bg);color:var(--ep-text)}.ep-wp .wp-block-comments-title{font-size:27px}.ep-wp .comment-form input:not([type=checkbox],[type=submit]),.ep-wp .comment-form textarea{max-width:100%;background:var(--ep-card);color:var(--ep-text);border:1px solid var(--ep-line);border-radius:8px;padding:10px}.ep-wp .comment-form input[type=submit]{border:0;border-radius:999px;padding:12px 20px;background:var(--ep-accent);color:var(--ep-ink)}.ep-wp .wp-block-post-comments-form{margin-top:35px}.ep-wp .ep-meta>.wp-block-group{gap:10px}.ep-wp .ep-rail .wp-block-latest-posts{padding-left:0;list-style:none;font-size:14px}.ep-wp .ep-rail .wp-block-latest-posts li{padding:15px 0;border-bottom:1px solid var(--ep-line)}.ep-wp .ep-rail .wp-block-latest-posts a{text-decoration:none}.ep-wp .ep-rail .wp-block-latest-posts__post-date{font:11px var(--ep-mono);color:var(--ep-muted);margin-top:8px}
@keyframes ep-orbit{to{transform:rotate(360deg)}}
@media(min-width:1500px){.ep-hero{padding-block:76px}.ep-hero h1{font-size:84px}}
@media(max-width:1080px){.ep-wrap{width:calc(100% - 40px)}.ep-hero{gap:28px}.ep-hero h1{letter-spacing:-2.8px}.ep-content-grid{grid-template-columns:minmax(0,1fr) 250px;gap:26px}.ep-rail{padding-left:22px}.ep-nav{gap:15px}.ep-header-inner{gap:20px}.ep-brand{font-size:23px}}
@media(max-width:800px){.ep-nav{display:none}.ep-tools{margin-left:auto}.ep-mobile{display:block}.ep-hero{grid-template-columns:1fr 1fr;padding-block:42px;gap:24px}.ep-hero h1{font-size:48px}.ep-cover{aspect-ratio:1}.ep-cover-top{inset:15px 15px auto;font-size:9px}.ep-cover-bottom{inset:auto 16px 18px}.ep-cover-bottom strong{font-size:24px}.ep-cover-bottom>span:last-child{display:none}.ep-content-grid{grid-template-columns:1fr}.ep-rail{padding-left:0;border-left:0;border-top:1px solid var(--ep-line);padding-top:30px;display:grid;grid-template-columns:1fr 1fr;gap:25px}.ep-rail>.ep-search{grid-column:1/-1;margin:0}.ep-rail>.widget{min-width:0}.ep-rail .ep-note{margin:0}.ep-banner{padding:27px;margin-bottom:45px}.ep-wp .ep-rail{display:block}.ep-wp .ep-rail>*{max-width:none}}
@media(max-width:560px){.ep-wrap{width:calc(100% - 32px)}.ep-header-inner{min-height:82px;gap:10px}.ep-brand{font-size:24px}.ep-brand small{font-size:9px}.ep-mark{width:32px;height:32px;font-size:23px;border-radius:8px}.ep-brand{gap:9px}.ep-tools{gap:7px}.ep-tools .ep-rss-icon{display:none}.ep-hero{grid-template-columns:1fr;padding-block:34px;gap:28px}.ep-hero h1{font-size:clamp(46px,12vw,66px);letter-spacing:-2.7px;margin:20px 0}.ep-lead{font-size:16px}.ep-cover{aspect-ratio:1.35}.ep-cover-top{inset:20px 20px auto;font-size:10px}.ep-cover-bottom{inset:auto 20px 20px}.ep-cover-bottom strong{font-size:30px}.ep-cover-bottom>span:last-child{display:block;font-size:12px}.ep-caption{font-size:10px}.ep-topics{gap:8px;padding-block:18px}.ep-topics>span{width:100%;margin-bottom:3px}.ep-chip{padding:9px 13px;font-size:12px}.ep-content-grid{padding-top:30px;gap:30px}.ep-section-heading h2{font-size:25px}.ep-section-heading p{font-size:10px}.ep-card-grid,.ep-wp .ep-card-grid.wp-block-post-template{grid-template-columns:1fr}.ep-card h3,.ep-wp .wp-block-post-title{font-size:26px}.ep-card p{font-size:15px}.ep-rail{grid-template-columns:1fr;gap:25px}.ep-banner{display:block;padding:25px}.ep-banner .ep-button{margin-top:22px}.ep-banner h2{font-size:26px}.ep-footer-top{flex-direction:column;gap:12px}.ep-footer-links{gap:20px}.ep-footer-bottom{gap:10px}.ep-article{padding-top:32px}.ep-article h1{letter-spacing:-1.6px}.ep-article-lead{font-size:18px}.ep-prose,.ep-wp .ep-article .wp-block-post-content{font-size:17px}.ep-prose h2{font-size:27px}.ep-prose blockquote{font-size:20px;padding-inline:18px}.ep-stats{grid-template-columns:1fr}.ep-archive-head h1{font-size:38px}.ep-wp .ep-header-inner .wp-block-navigation{margin-left:auto}.ep-wp .ep-header-inner{flex-wrap:wrap}.ep-wp .ep-header-inner .ep-tools{margin-left:0}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
@media print{body{background:#fff;color:#111}.ep-header,.ep-tools,.ep-topics,.ep-rail,.ep-banner,.ep-share,.ep-footer{display:none}.ep-wrap{width:100%}.ep-content-grid{display:block}.ep-prose a{color:#111}.ep-article{max-width:100%}.ep-article h1{font-size:32px}.ep-prose{font-size:12pt}}

/* Explicit component spacing: WordPress global block-gap must not collapse menus. */
.ep-wp .ep-header-inner > .wp-block-navigation{margin-left:auto}
.ep-wp .ep-header-inner > .wp-block-navigation > .wp-block-navigation__container,
.ep-wp .wp-block-navigation .wp-block-navigation__container,
.ep-wp .ep-footer .wp-block-navigation__container{gap:24px}
.ep-wp .wp-block-navigation .wp-block-page-list{gap:24px;display:flex;flex-wrap:wrap}
.ep-wp .ep-brand{gap:12px;flex-shrink:0}
.ep-wp .ep-brand .wp-block-site-title{font-size:27px;font-weight:750;line-height:1.1;letter-spacing:-1.2px;margin:0}
.ep-wp .ep-brand .wp-block-site-title a{text-decoration:none}
.ep-wp .ep-brand .wp-block-site-tagline{font:10px/1.5 var(--ep-mono);color:var(--ep-muted);letter-spacing:1px;text-transform:uppercase;margin:7px 0 0;max-width:245px;white-space:normal}
.ep-wp .ep-rail > *{margin-block:0 32px}
.ep-wp .ep-rail > :last-child{margin-bottom:0}
.ep-wp .ep-rail .wp-block-heading{margin:0 0 18px}
.ep-wp .ep-rail .wp-block-latest-posts{margin-top:0;margin-bottom:32px}
.ep-wp .ep-rail .wp-block-categories-list{margin:0 0 32px;padding:0;list-style:none}
.ep-wp .ep-rail .wp-block-categories-list li{padding:12px 0;border-bottom:1px solid var(--ep-line);font-size:14px}
.ep-wp .ep-rail .wp-block-categories-list a{text-decoration:none}
.ep-wp .ep-banner{margin-bottom:64px}
.ep-wp .ep-card-grid .ep-meta{display:flex;gap:14px;flex-wrap:wrap;margin-top:18px}
.ep-wp .ep-card-grid > li{padding-bottom:28px}
.ep-wp .ep-footer .wp-block-navigation{margin-left:auto}
.ep-wp .ep-footer-top{margin-bottom:30px}
.ep-wp .ep-footer .wp-block-site-title{line-height:1.2}
.ep-wp .ep-footer p{margin-top:12px}
.ep-wp .wp-block-query-pagination{padding-top:8px;min-height:44px}
.ep-card-grid{row-gap:36px;column-gap:28px}
.ep-card h2,.ep-card h3{margin-top:12px;margin-bottom:14px}
.ep-topics{column-gap:12px;row-gap:12px}
@media(max-width:800px){.ep-wp .ep-header-inner{gap:16px}.ep-wp .ep-brand .wp-block-site-title{font-size:25px}.ep-wp .wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation__container{gap:20px;align-items:flex-start}.ep-wp .wp-block-navigation__responsive-container.is-menu-open .wp-block-page-list{flex-direction:column;align-items:flex-start;gap:20px}.ep-wp .ep-banner{margin-bottom:45px}}
@media(max-width:560px){.ep-wp .ep-brand .wp-block-site-tagline{font-size:9px;max-width:190px}.ep-wp .ep-footer .wp-block-navigation{margin-left:0}.ep-card-grid{row-gap:32px}.ep-wp .ep-header-inner .ep-tools{margin-left:0}.ep-wp .ep-header-inner > .wp-block-navigation{margin-left:auto}}

[hidden]{display:none!important}

/* Keep the public surface entirely Epoch-owned, including on restored blogs. */
.ep-blogger #navbar-iframe,.ep-blogger #navbar,.ep-blogger .navbar,.ep-blogger .Attribution{display:none!important}
.ep-blogger .widget:not(.Blog):not(.Label):not(.BlogArchive):not(.HTML):not(.PageList){display:none!important}
.ep-blogger .ep-rail .widget{margin-block:0 28px}
.ep-blogger .ep-rail .widget:last-child{margin-bottom:0}
/* Blogger may carry widgets from the previous theme into the new sidebar. */
.ep-blogger .ep-rail .Header,.ep-blogger .ep-rail .BlogSearch{display:none}
.ep-blogger .ep-rail .Profile{padding:22px;border:1px solid var(--ep-line);border-radius:12px;background:var(--ep-card)}
.ep-blogger .ep-rail .Profile h2{margin:0 0 16px;font-size:18px}
.ep-blogger .ep-rail .Profile img{width:48px;height:48px;object-fit:cover;border-radius:50%;margin-inline-end:12px}
.ep-blogger .ep-rail .Profile .profile-img{float:inline-start}
.ep-blogger .ep-rail .Profile .profile-textblock,.ep-blogger .ep-rail .Profile .profile-link{font-size:13px;line-height:1.7}
.ep-blogger .ep-rail .Profile .widget-content{display:flow-root}
.ep-blogger .ep-rail .HTML h2{margin-bottom:16px}
.ep-blogger .ep-rail .HTML .widget-content{font-size:14px;line-height:1.8;overflow-wrap:anywhere}
.ep-blogger .ep-rail .HTML a{display:inline-flex;align-items:center;min-height:44px;color:var(--ep-accent)}
.ep-blogger .ep-rail .ReportAbuse{font-size:12px;border-top:1px solid var(--ep-line);padding-top:16px}
.ep-blogger .ep-footer .PageList h2{display:none}
.ep-blogger .ep-footer .PageList ul{gap:20px;margin:0;padding:0;display:flex;flex-wrap:wrap}
.ep-blogger .ep-footer .PageList a{min-height:44px;display:inline-flex;align-items:center;text-decoration:none}
.ep-blogger .ep-footer .Attribution{margin-top:16px;font-size:11px;color:var(--ep-muted)}
body#layout .widget{display:block!important}

body#layout .ep-hero,body#layout .ep-topics,body#layout .ep-banner{display:none}body#layout .ep-content-grid{display:block}body#layout .ep-rail{padding:0;border:0}body#layout .section{min-height:80px;margin:15px}

body.script:
//
/* No tracking, external requests or wallet access. */
(()=>{'use strict';
const root=document.documentElement;
try{const saved=localStorage.getItem('gonk-epoch-mode');if(['paper','dark'].includes(saved))root.dataset.epochMode=saved;}catch{}
for(const button of document.querySelectorAll('[data-epoch-toggle]')){
 button.hidden=false;
 const update=()=>{const paper=root.dataset.epochMode==='paper';button.setAttribute('aria-pressed',String(paper));button.setAttribute('aria-label',paper?'Switch to dark theme':'Switch to paper theme');};
 update();button.addEventListener('click',()=>{root.dataset.epochMode=root.dataset.epochMode==='paper'?'dark':'paper';try{localStorage.setItem('gonk-epoch-mode',root.dataset.epochMode);}catch{}update();});
}
const menu=document.querySelector('.ep-mobile');
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu?.open){menu.open=false;menu.querySelector('summary')?.focus();}});
for(const button of document.querySelectorAll('[data-epoch-copy]')){button.hidden=false;button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.href);button.textContent='Link copied';}catch{button.textContent='Copy the address from your browser';}});}
})();

if(document.body.id!=='layout'){for(const widget of document.querySelectorAll('.ep-rail .HTML')){const content=widget.querySelector('.widget-content');if(content&&!content.textContent.trim()&&!content.querySelector('img,iframe,video,a'))widget.hidden=true;}}

//
